-- seed 828 :: es translations 281-290

INSERT INTO translation_intake (original, locale, body) VALUES
    ('A hero is an ordinary individual who finds the strength to persevere and endure in spite of overwhelming obstacles.', 'es',
     'Un héroe es una persona común que encuentra la fuerza para perseverar y resistir a pesar de obstáculos abrumadores.'),
    ('What lies behind us and what lies before us are tiny matters compared to what lies within us.', 'es',
     'Lo que queda atrás y lo que tenemos por delante son asuntos minúsculos comparados con lo que hay dentro de nosotros.'),
    ('The greatest test of courage on earth is to bear defeat without losing heart.', 'es',
     'La mayor prueba de valor en la Tierra es soportar la derrota sin perder el ánimo.'),
    ('Of all the virtues we can learn, no trait is more useful, more essential for survival, and more likely to improve the quality of life than the ability to transform adversity into an enjoyable challenge.', 'es',
     'De todas las virtudes que podemos aprender, ningún rasgo es más útil, más esencial para sobrevivir y más capaz de mejorar la calidad de vida que la capacidad de transformar la adversidad en un desafío placentero.');
